<section class="dashboard-shell"><div class="container"><div class="dashboard-head"><div><span class="eyebrow"><span></span> حسابي</span><h1>الملف الشخصي</h1><p>حدّث بيانات الحساب وكلمة المرور من مكان واحد.</p></div></div><div class="profile-grid"><section class="panel profile-card"><div class="profile-avatar"><?= e(mb_substr($profile['name'], 0, 1)) ?></div><h2><?= e($profile['name']) ?></h2><span class="role-badge role-<?= e($profile['role']) ?>"><?= e(role_label($profile['role'])) ?></span><p><?= e($profile['email']) ?></p></section><div class="profile-forms"><section class="panel profile-details"><h2>البيانات الأساسية</h2><form method="post" action="<?= url('/profile') ?>" class="form-grid booking-form"><?= csrf_field() ?><label>الاسم<input name="name" value="<?= e($profile['name']) ?>" required minlength="3"></label><label>رقم الجوال<input name="phone" value="<?= e($profile['phone']) ?>" required></label><label>تاريخ الميلاد<input type="date" name="date_of_birth" value="<?= e($profile['date_of_birth'] ?? '') ?>"></label><label>العنوان<input name="address" value="<?= e($profile['address'] ?? '') ?>" maxlength="255"></label><button class="button button-primary" type="submit">حفظ البيانات</button></form></section><section class="panel profile-details"><h2>تغيير كلمة المرور</h2><form method="post" action="<?= url('/profile/password') ?>" class="form-grid booking-form"><?= csrf_field() ?><label class="field-span">كلمة المرور الحالية<input type="password" name="current_password" required></label><label>كلمة المرور الجديدة<input type="password" name="password" minlength="10" required></label><label>تأكيد كلمة المرور<input type="password" name="password_confirmation" minlength="10" required></label><button class="button button-primary" type="submit">تغيير كلمة المرور</button></form></section></div></div></div></section>
